请对以下 case 进行三维加权评分。

=== case_id ===
Case-08-sleep-003

=== 用户原始指令 (query.txt) ===
给我做个睡眠问卷那种,能打勾选的,点一下能进系统设置,睡眠不好就显示红色警告嘛

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我做个睡眠问卷那种,能打勾选的,点一下能进系统设置,睡眠不好就显示红色警告嘛",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "sleepQuestionnaire": {
      "title": {
        "type": "string",
        "description": "睡眠问卷卡片标题。",
        "sampleValue": "睡眠问卷"
      },
      "statusLabel": {
        "type": "string",
        "description": "睡眠状态警告文案，用于在睡眠不好时提示关注。",
        "sampleValue": "睡眠不好"
      },
      "primaryHint": {
        "type": "string",
        "description": "睡眠问卷当前结果的简短提示。",
        "sampleValue": "需关注"
      },
      "item1Label": {
        "type": "string",
        "description": "第一项睡眠问卷选项文案。",
        "sampleValue": "入睡难"
      },
      "item1Selected": {
        "type": "boolean",
        "description": "第一项睡眠问卷是否已勾选。",
        "sampleValue": true
      },
      "item2Label": {
        "type": "string",
        "description": "第二项睡眠问卷选项文案。",
        "sampleValue": "夜醒多"
      },
      "item2Selected": {
        "type": "boolean",
        "description": "第二项睡眠问卷是否已勾选。",
        "sampleValue": true
      },
      "actionLabel": {
        "type": "string",
        "description": "进入系统设置的短动作文案。",
        "sampleValue": "打开设置"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_sleep.png",
      "description": "睡眠图标，适合用于睡眠问卷、睡眠监督或休息状态的主视觉识别。"
    }
  ]
}

